from typing import List


def max_submatrix_sum_size(matrix: List[List[int]], threshold: int) -> int:
    n = len(matrix)
    pre = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n):
        for j in range(n):
            pre[i + 1][j + 1] = matrix[i][j] + pre[i][j + 1] + pre[i + 1][j] - pre[i][j]

    def ok(s: int) -> bool:          # 所有 s×s 子矩阵的和都 < threshold
        for i in range(n - s + 1):
            for j in range(n - s + 1):
                if pre[i + s][j + s] - pre[i][j + s] - pre[i + s][j] + pre[i][j] >= threshold:
                    return False
        return True

    lo, hi = 0, n                     # 不变式：ok(lo) 成立（s=0 视为成立）
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if ok(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

class Solution {
    public int maxSubmatrixSumSize(int[][] matrix, int threshold) {
        int n = matrix.length;
        long[][] pre = new long[n + 1][n + 1];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                pre[i + 1][j + 1] = matrix[i][j] + pre[i][j + 1] + pre[i + 1][j] - pre[i][j];
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            boolean ok = true;
            for (int i = 0; i + mid <= n && ok; i++)
                for (int j = 0; j + mid <= n && ok; j++)
                    if (pre[i + mid][j + mid] - pre[i][j + mid] - pre[i + mid][j] + pre[i][j] >= threshold) ok = false;
            if (ok) lo = mid; else hi = mid - 1;
        }
        return lo;
    }
}

